using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]
public static class DashContactPlayChecks
{
 const string Key="DimensionShifter.DashContactChecks";
 static PlayerAttack attack;static PlayerHealth health;static PlayerEnemyContact contact;static EnemyHealth enemy;static Rigidbody2D body,enemyBody;static int phase;static bool traced;static float since;static string report;
 static DashContactPlayChecks(){if(SessionState.GetBool(Key,false))EditorApplication.update+=Update;}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/PaintedDimension.unity");UnityEngine.Object.FindAnyObjectByType<LevelGenerator>().enabled=false;UnityEngine.Object.FindAnyObjectByType<PlayerMovement>().enabled=false;UnityEngine.Object.FindAnyObjectByType<EnemyPatrol>().enabled=false;SessionState.SetBool(Key,true);EditorApplication.isPlaying=true;}
 static void Need(bool b,string why){if(!b)throw new Exception(why);}
 static void Pass(string why){report+="PASS "+why+"\n";}
 static void Place(float x){enemyBody.position=new Vector2(x,1);enemy.transform.position=new Vector3(x,1,0);Physics2D.SyncTransforms();}
 static void Update(){if(!EditorApplication.isPlaying)return;try{
 if(phase==0){Physics2D.simulationMode=SimulationMode2D.FixedUpdate;attack=UnityEngine.Object.FindAnyObjectByType<PlayerAttack>();health=attack.GetComponent<PlayerHealth>();contact=attack.GetComponent<PlayerEnemyContact>();body=attack.GetComponent<Rigidbody2D>();body.interpolation=RigidbodyInterpolation2D.None;body.constraints=RigidbodyConstraints2D.FreezeAll;body.gravityScale=0;body.position=new Vector2(0,1);attack.transform.position=new Vector3(0,1,0);attack.transform.localScale=new Vector3(Mathf.Abs(attack.transform.localScale.x),attack.transform.localScale.y,1);enemy=UnityEngine.Object.FindAnyObjectByType<EnemyHealth>();enemyBody=enemy.GetComponent<Rigidbody2D>();enemyBody.interpolation=RigidbodyInterpolation2D.None;enemyBody.gravityScale=0;enemyBody.constraints=RigidbodyConstraints2D.FreezeAll;enemy.maxHealth=10;typeof(EnemyHealth).GetField("<CurrentHealth>k__BackingField",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(enemy,10);Place(1.9f);attack.StartCoroutine("NormalAttackRoutine");phase=1;since=Time.realtimeSinceStartup;}
 else if(phase==1&&Time.realtimeSinceStartup-since>.8f){Need(enemy.CurrentHealth==9,"Safe-range swing missed: hp="+enemy.CurrentHealth);Need(health.currentHealth==100,"Ranged strike caused contact damage");Pass("normal swing reaches a live slime without touching or taking damage");Place(.8f);phase=2;since=Time.realtimeSinceStartup;}
 else if(phase==2&&Time.realtimeSinceStartup-since>.3f){Need(health.currentHealth==80,"Real collision did not deal 20 damage: "+health.currentHealth);Pass("actual slime contact deals one 20-HP hit despite multiple colliders");phase=3;since=Time.realtimeSinceStartup;}
 else if(phase==3&&Time.realtimeSinceStartup-since>.5f){Need(health.currentHealth==80,"Damage repeats during invincibility");Place(10);phase=4;since=Time.realtimeSinceStartup;}
 else if(phase==4&&Time.realtimeSinceStartup-since>2.1f){Need(!health.IsInvincible,"Cooldown failed to expire");Place(1.9f);body.constraints=RigidbodyConstraints2D.FreezeRotation;attack.StartCoroutine("DashAttackRoutine");Need(contact.IsContactProtected,"Dash protection not activated");phase=5;since=Time.realtimeSinceStartup;}
 else if(phase==5&&!traced&&Time.realtimeSinceStartup-since>.15f){traced=true;report+="TRACE player="+body.position+" velocity="+body.linearVelocity+" constraints="+body.constraints+" simulated="+body.simulated+" dash="+attack.IsDashing+" mask="+attack.GetComponent<Collider2D>().excludeLayers.value+"\n";foreach(var h in Physics2D.BoxCastAll(body.position,Vector2.one,0,Vector2.right,5,(1<<8)|(1<<9)))report+="BLOCK "+h.collider.name+" at "+h.point+"\n";}
 else if(phase==5&&Time.realtimeSinceStartup-since>.8f){Need(health.currentHealth==80,"Dash contact dealt damage");Need(enemy.CurrentHealth==7,"Dash did not hit exactly once: "+enemy.CurrentHealth);Need(body.position.x>enemy.GetComponent<Collider2D>().bounds.max.x+.5f,"Dash did not cross live slime: "+body.position);Need(attack.GetComponent<Collider2D>().excludeLayers==0,"Collision exclusion leaked");Need(!contact.IsContactProtected,"Dash immunity leaked");Pass("B crosses a surviving slime, deals 2 HP once, takes no contact damage and restores collision");Place(body.position.x+.8f);phase=6;since=Time.realtimeSinceStartup;}
 else if(phase==6&&Time.realtimeSinceStartup-since>.3f){Need(health.currentHealth==60,"Contact damage did not return after dash");Pass("contact damage resumes after dash/exit grace");var audio=UnityEngine.Object.FindAnyObjectByType<GameAudio>();Need(audio!=null&&audio.GetComponents<AudioSource>().Length==8,"Missing bounded audio pool");Pass("runtime swing/dash/hit/hurt cues use the eight-voice audio pool");Finish(0);}
 }catch(Exception e){report+="FAIL "+e+"\n";Finish(1);}}
 static void Finish(int code){SessionState.SetBool(Key,false);EditorApplication.update-=Update;File.WriteAllText("dash-contact-play-results.txt",report);EditorApplication.Exit(code);}
}
